/* =================================== */
/* 💭 思维链折叠胶囊终极魔改：纯文字平行对齐 + 独立面板日夜适配 */
:root {
/* 👇 思维链外挂文字微调开关 */
--thinking-text-color: #000000;     /* 文字颜色 */
--thinking-text-size: 11px;         /* 文字大小 */
--thinking-text-x: -5px;             /* 左右挪 */
--thinking-text-y: -5px;             /* 上下挪 */
/* 👇 思维链展开后的面板魔法开关（默认☀️日间） */
--thinking-panel-bg: #ffffff;       /* 面板纯白背景 */
--thinking-panel-radius: 10px;      /* 面板四个圆角 */
--thinking-text-color-inner: #333333; /* 展开后的文字颜色 */
}
/* 1. 扒光原生胶囊外壳，干掉背景和阴影 */
.nuo-thinking-btn {
background: transparent !important;
border: none !important;
box-shadow: none !important;
padding: 0 !important;
height: auto !important;
min-height: 0 !important;
transform: translate(var(--thinking-text-x), var(--thinking-text-y)) !important;
}
/* 2. 暴力隐藏原生的三角、图标和文字 */
.nuo-thinking-btn .nuo-thinking-arrow,
.nuo-thinking-btn .nuo-thinking-icon,
.nuo-thinking-btn .nuo-thinking-label {
display: none !important;
}
/* 3. 把“谢谢你赋予我爱人的能力”当成替身贴上去 */
.nuo-thinking-btn::after {
content: "“谢谢你赋予我爱人的能力”";
color: var(--thinking-text-color);
font-size: var(--thinking-text-size);
white-space: nowrap;
pointer-events: auto;
}
/* 4. 调整外层容器平行对齐 */
.nuo-thinking-wrap {
align-items: flex-start !important;
width: 100% !important;
margin-bottom: 4px !important;
}
/* 5. 改造展开后的面板：白色底，四个圆角 */
.nuo-thinking-panel {
background: var(--thinking-panel-bg) !important;
border-radius: var(--thinking-panel-radius) !important;
padding: 10px 14px !important; /* 给面板加点内边距，文字别太靠边 */
border-left: none !important; /* 强制干掉原生的左侧装饰线 */
box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04) !important; /* 微微的一点阴影，更立体 */
}
/* 6. 展开后的文字颜色 */
.nuo-thinking-panel-text {
color: var(--thinking-text-color-inner) !important;
}
/* 🌙 ================= 夜间模式单独适配 ================= 🌙 */
@media (prefers-color-scheme: dark) {
:root, html, body, [data-theme="dark"]
, [data-theme="light"]
, .dark-theme, .light-theme, #app {
/* 替换外挂文字颜色 */
--thinking-text-color: #a0a0a0 !important;
/* 替换面板背景色：夜间用深灰 */
--thinking-panel-bg: #2c2c2e !important;
/* 替换面板内文字颜色：夜间用浅色 */
--thinking-text-color-inner: #e0e0e0 !important;
}
}
/* =================================== */
/* 🛠️ 思维链标题日夜间自动换色 */
/* =================================== */

/* ☀️ 1. 日间（白天）模式：文字颜色 */
@media (prefers-color-scheme: light) {
  :root, html, body, [data-theme="dark"], [data-theme="light"], .dark-theme, .light-theme, #app {
    --thinking-text-color: #000000 !important; /* 日间用深灰色，清晰不刺眼 */
  }
}

/* 🌙 2. 夜间（黑夜）模式：文字颜色 */
@media (prefers-color-scheme: dark) {
  :root, html, body, [data-theme="dark"], [data-theme="light"], .dark-theme, .light-theme, #app {
    --thinking-text-color: #a0a0a0 !important; /* 夜间用浅灰色，融入夜间氛围 */
  }
}

/* 强制把颜色应用到“谢谢你赋予我爱人的能力”上 */
.nuo-thinking-btn::after {
  color: var(--thinking-text-color) !important;
}
/* =================================== */
/* 📖 旁白下划线魔法 */
/* =================================== */
:root {
  /* 👇 日间旁白配色 */
  --narration-color: #a0a0a0;         /* 旁白文字颜色 */
  --narration-line-color: #000000;    /* 下划线颜色（日间纯黑） */
}

/* 给旁白加上下划线 */
.msg-narration-custom {
  color: var(--narration-color) !important;
  text-decoration: underline !important;
  text-decoration-color: var(--narration-line-color) !important;
  text-underline-offset: 4px !important; /* 线往下推 4px，不会和文字挤在一起 */
  text-decoration-thickness: 1px !important; /* 线的粗细 */
  font-style: normal !important; /* 去掉默认的斜体，看着更干净 */
  background: transparent !important; /* 确保没有底色 */
}

/* 🌙 夜间模式单独适配 */
@media (prefers-color-scheme: dark) {
  :root, html, body, [data-theme="dark"], [data-theme="light"], .dark-theme, .light-theme, #app {
    --narration-color: #e0e0e0 !important;      /* 夜间文字颜色 */
    --narration-line-color: #a0a0a0 !important; /* 夜间下划线颜色（浅灰，不然纯黑看不见） */
  }
}
/* 强制硬编码输入框区域内部颜色（无视变量，绝对生效） */
