    background-color: #ffffff !important;  /* 日间颜色 */
    border-color: #ffffff !important;      /* 日间边框 */
}

@media (prefers-color-scheme: dark) {
    .input-action-bar-custom::before {
        background-color: #272727 !important; /* 夜间颜色 */
        border-color: #272727 !important;     /* 夜间边框 */
    }
}

.input-box-custom {
    color: #222222 !important;
}

@media (prefers-color-scheme: dark) {
    .input-box-custom {
        color: #f0f0f0 !important;
    }
}

