  font-size: 0 !important;
}

.msg-them .msg-reply-detached-name::before {
  content: "Yoyo";
  font-size: 13px !important;
  color: var(--reply-detached-name-color) !important;
}

.msg-reply-detached-name::after {
    content: "：" !important;
    font-size: 13px !important;
    color: var(--reply-detached-name-color) !important;
}
